/* Required rule for elements using hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-primary: #f8fafc;
  --text-muted: #94a3b8;
  --accent: #38bdf8;
  --accent-hover: #0284c7;
  --accent-active: #0369a1;
  --danger: #f43f5e;
  --success: #10b981;
  --focus-ring: #f59e0b;
  --border-color: #334155;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-color);
  color: var(--text-primary);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.game-container {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 1rem;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  min-width: 320px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  text-align: center;
}

.game-header {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.game-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.game-instructions {
  font-size: 1rem;
  color: var(--text-muted);
}

.target-rgb {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.35rem;
  font-weight: 700;
  padding: 0.75rem 1rem;
  background-color: rgba(15, 23, 42, 0.7);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  color: var(--accent);
  user-select: all;
}

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.score-card {
  background-color: rgba(15, 23, 42, 0.5);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.score-label {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.score-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
}

.swatches-container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.875rem;
  justify-content: center;
}

.swatch-btn {
  aspect-ratio: 1 / 1;
  width: 100%;
  border: 3px solid transparent;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.2);
}

.swatch-btn:hover:not(:disabled) {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
  border-color: rgba(255, 255, 255, 0.5);
}

.swatch-btn:active:not(:disabled) {
  transform: translateY(0) scale(0.98);
}

.swatch-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 3px;
}

.swatch-btn:disabled {
  cursor: not-allowed;
  opacity: 0.85;
}

.game-status {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  min-height: 4.5rem;
  justify-content: center;
}

.status-text {
  font-size: 1.125rem;
  font-weight: 600;
}

.status-text.success {
  color: var(--success);
}

.status-text.failure {
  color: var(--danger);
}

.action-btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.625rem 1.5rem;
  border: none;
  border-radius: 0.5rem;
  background-color: var(--accent);
  color: #0f172a;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.action-btn:hover {
  background-color: var(--accent-hover);
  color: #ffffff;
}

.action-btn:active {
  background-color: var(--accent-active);
  transform: scale(0.98);
}

.action-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

@media (max-width: 400px) {
  .game-container {
    padding: 1.25rem;
  }

  .game-title {
    font-size: 1.5rem;
  }

  .target-rgb {
    font-size: 1.15rem;
  }

  .swatches-container {
    gap: 0.5rem;
  }
}

function initGame() {
  const STORAGE_KEY = 'pixel_color_guess_best_streak';

  const targetRgbEl = document.getElementById('targetRgb');
  const currentStreakEl = document.getElementById('currentStreak');
  const bestStreakEl = document.getElementById('bestStreak');
  const swatchesContainer = document.getElementById('swatchesContainer');
  const swatchButtons = Array.from(document.querySelectorAll('.swatch-btn'));
  const statusMessageEl = document.getElementById('statusMessage');
  const actionBtn = document.getElementById('actionBtn');

  let currentStreak = 0;
  let bestStreak = 0;
  let correctIndex = 0;
  let currentColors = [];
  let isRoundActive = true;

  function loadBestStreak() {
    try {
      const saved = window.localStorage ? window.localStorage.getItem(STORAGE_KEY) : null;
      if (saved !== null) {
        bestStreak = parseInt(saved, 10) || 0;
      }
    } catch (e) {
      // Fallback if localStorage access is denied in sandboxed environments
    }
    bestStreakEl.textContent = bestStreak;
  }

  function updateBestStreak() {
    if (currentStreak > bestStreak) {
      bestStreak = currentStreak;
      bestStreakEl.textContent = bestStreak;
      try {
        if (window.localStorage) {
          window.localStorage.setItem(STORAGE_KEY, bestStreak.toString());
        }
      } catch (e) {
        // Fallback if localStorage access is denied in sandboxed environments
      }
    }
  }

  function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
  }

  function getRandomRgb() {
    return {
      r: getRandomInt(0, 255),
      g: getRandomInt(0, 255),
      b: getRandomInt(0, 255)
    };
  }

  function rgbToString(c) {
    return `rgb(${c.r}, ${c.g}, ${c.b})`;
  }

  function colorDistance(c1, c2) {
    return Math.sqrt(
      Math.pow(c1.r - c2.r, 2) +
      Math.pow(c1.g - c2.g, 2) +
      Math.pow(c1.b - c2.b, 2)
    );
  }

  function generateDistinctColor(existingColors, minDistance = 45) {
    let color;
    let attempts = 0;
    do {
      color = getRandomRgb();
      attempts++;
    } while (
      attempts < 100 &&
      existingColors.some(existing => colorDistance(color, existing) < minDistance)
    );
    return color;
  }

  function startNewRound() {
    isRoundActive = true;
    statusMessageEl.textContent = '';
    statusMessageEl.className = 'status-text';
    actionBtn.hidden = true;

    const targetColor = getRandomRgb();
    const colors = [targetColor];

    while (colors.length < 3) {
      colors.push(generateDistinctColor(colors));
    }

    correctIndex = getRandomInt(0, 2);
    const randomizedColors = [];
    const distractors = [colors[1], colors[2]];

    for (let i = 0; i < 3; i++) {
      if (i === correctIndex) {
        randomizedColors.push(targetColor);
      } else {
        randomizedColors.push(distractors.pop());
      }
    }

    currentColors = randomizedColors;
    targetRgbEl.textContent = rgbToString(targetColor);

    swatchButtons.forEach((btn, index) => {
      btn.style.backgroundColor = rgbToString(currentColors[index]);
      btn.disabled = false;
      btn.setAttribute('aria-label', `Color option ${index + 1}`);
    });
  }

  function handleGuess(index) {
    if (!isRoundActive) return;

    if (index === correctIndex) {
      currentStreak++;
      currentStreakEl.textContent = currentStreak;
      updateBestStreak();
      statusMessageEl.textContent = 'Correct! Next color...';
      statusMessageEl.className = 'status-text success';

      isRoundActive = false;
      setTimeout(() => {
        startNewRound();
      }, 800);
    } else {
      isRoundActive = false;
      statusMessageEl.textContent = `Game Over! Your streak was ${currentStreak}.`;
      statusMessageEl.className = 'status-text failure';
      currentStreak = 0;
      currentStreakEl.textContent = currentStreak;

      swatchButtons.forEach(btn => {
        btn.disabled = true;
      });

      actionBtn.hidden = false;
      actionBtn.focus();
    }
  }

  swatchesContainer.addEventListener('click', (event) => {
    const btn = event.target.closest('.swatch-btn');
    if (!btn) return;
    const index = swatchButtons.indexOf(btn);
    if (index !== -1) {
      handleGuess(index);
    }
  });

  actionBtn.addEventListener('click', () => {
    startNewRound();
  });

  loadBestStreak();
  startNewRound();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initGame);
} else {
  initGame();
}
